import itertools

def solve_N(N, S):
    def get_next(state, k, s):
        new_state = list(state)
        for i in range(N):
            if i < k:
                new_state[i] += s
            else:
                new_state[i] -= s
        return tuple(new_state)

    states = []
    for state in itertools.product(range(0, S+1), repeat=N):
        if sum(state) <= S:
            states.append(state)

    is_losing = {state: any(x == 0 for x in state) for state in states}

    changed = True
    while changed:
        changed = False
        for state in states:
            if not is_losing[state]:
                for k in range(1, N):
                    all_s_losing = True
                    for s in [1, -1]:
                        nxt = get_next(state, k, s)
                        if any(x > S for x in nxt) or sum(nxt) > S:
                            all_s_losing = False
                            break
                        if not is_losing[nxt]:
                            all_s_losing = False
                            break
                    if all_s_losing:
                        is_losing[state] = True
                        changed = True
                        break

    min_n = 100
    for state in states:
        if not is_losing[state]:
            min_n = min(min_n, sum(state))
    return min_n

