def solve_N(N, S):
    def get_next(state, k, s):
        new_state = list(state)
        for i in range(N):
            if i < k:
                new_state[i] += s
            else:
                new_state[i] -= s
        return tuple(new_state)

    states = []
    # Using a more memory-efficient way to generate states
    # This is still going to be slow.
    # Let's use a subset of states.
    # We only need states where sum is <= S.

    # Actually, the number of states is not that large for small S.
    # Let's use a dictionary to avoid storing all states.
    is_losing = {}

    # Generate states with sum <= S
    def generate_states(idx, current_sum, current_state):
        if idx == N:
            is_losing[tuple(current_state)] = any(x == 0 for x in current_state)
            return
        for x in range(S - current_sum + 1):
            current_state.append(x)
            generate_states(idx + 1, current_sum + x, current_state)
            current_state.pop()

    generate_states(0, 0, [])

    changed = True
    while changed:
        changed = False
        for state in list(is_losing.keys()):
            if not is_losing[state]:
                for k in range(1, N):
                    all_s_losing = True
                    for s in [1, -1]:
                        nxt = get_next(state, k, s)
                        if any(x > S for x in nxt) or sum(nxt) > S:
                            all_s_losing = False
                            break
                        if not is_losing.get(nxt, False): # If not in is_losing, we assume not losing
                            all_s_losing = False
                            break
                    if all_s_losing:
                        is_losing[state] = True
                        changed = True
                        break

    min_n = 1000
    for state, losing in is_losing.items():
        if not losing:
            min_n = min(min_n, sum(state))
    return min_n

